# Etude keys whose Completed state still means the event happened (Main.BuildState reads Playing OR Completed for them):
# a parent completion cascades Completed onto every started child (18-ETUDE-BINDING-AUDIT).
PERMANENT = ('hepzamirah.dead',)

LIST_KINDS = {"SeenCues", "QuestObjectives"}


def _keys(scene):
    for field in ("Requires", "Forbids"):
        yield from scene.get(field) or []
    for group in scene.get("RequiresAnyGroups") or []:
        yield from group
    for node in scene.get("Nodes") or []:
        for choice in node.get("Choices") or []:
            yield from choice.get("Requires") or []
            yield from choice.get("Forbids") or []
        for para in node.get("Paragraphs") or []:
            yield from para.get("Requires") or []
            yield from para.get("Forbids") or []
            for group in para.get("AnyGroups") or []:
                yield from group


def _bound(payload, key):
    kinds = ("Etudes", "CompletedQuests", "SeenCues", "SelectedAnswers", "StartedDialogs", "CompletedEtudes",
             "UnlockableFlags", "QuestObjectives", "InventoryItems", "StartedQuests", "MainCharacterFacts", "Latches", "Derived")
    return any(key in (payload.get(k) or {}) for k in kinds)


def integrate(payload):
    """Bind every world key read by a registered scene (transitively through Derived/Latches). Never overrides an
    existing binding: the registered routes' own keys win, and a conflicting GUID is an error."""
    # Ledger row 16 (R6 audit, COX): a page that mourns a sacrificed Commander never plays beside a Commander who came back
    # (the punchline groups, Last Call's flask, Iomedae's bridge). Like Last Call's L6, but for every commander_back world.
    for s in payload["Scenes"]:
        if (s.get("Owner", "").endswith("Epilogue") and "sacrifice" in (s.get("Requires") or [])
                and "trickster.commander_back" not in s["Forbids"]
                and "trickster.commander_back" not in (s.get("ForbidOverrides") or {}).values()):
            s["Forbids"].append("trickster.commander_back")
    pending = sorted({k for s in payload["Scenes"] for k in _keys(s)}
                     | {k for p in (payload.get("Presences") or {}).values()
                        for k in [*(p.get("Requires") or []), *(p.get("Forbids") or []),
                                  *(k for g in p.get("RequiresAnyGroups") or [] for k in g)]})
    routed = set()
    while pending:
        key = pending.pop()
        if key in BINDINGS:
            kind, guid, _ = BINDINGS[key]
            value = [guid] if kind in LIST_KINDS and isinstance(guid, str) else guid
            have = (payload.get(kind) or {}).get(key)
            if have is not None and have != value:
                raise ValueError("Conflicting world binding %s: %r vs %r" % (key, have, value))
            if not _bound(payload, key):
                payload.setdefault(kind, {})[key] = value
        elif key in DERIVED and not _bound(payload, key):
            payload.setdefault("Derived", {})[key] = [list(g) for g in DERIVED[key]]
            pending.extend(k for g in DERIVED[key] for k in g)
        elif key in LATCHES and not _bound(payload, key):
            payload.setdefault("Latches", {})[key] = list(LATCHES[key])
            pending.extend(LATCHES[key])
        elif key in (payload.get("Latches") or {}) and key not in routed:
            # A route bound this latch itself (e.g. iz.monster_dead.latched): its native sources still bind here.
            routed.add(key)
            pending.extend(payload["Latches"][key])
    permanent = {k for k in PERMANENT if k in (payload.get("Etudes") or {})}
    if permanent:
        payload["PermanentEtudes"] = sorted(set(payload.get("PermanentEtudes", [])) | permanent)
